import sys

data = sys.stdin.read().split()
n = int(data[0])
s = list(map(int, data[1:1 + n]))
best = None

def jumps(seq):
    return max(abs(seq[k + 1] - seq[k]) for k in range(len(seq) - 1))

for mask in range(3 ** (n - 2)):
    out, mid = [s[0]], []
    m = mask
    for i in range(1, n - 1):
        t = m % 3
        m //= 3
        if t == 1:
            out.append(s[i])
        elif t == 2:
            mid.append(s[i])
    out.append(s[-1])
    back_seq = [s[-1]] + mid[::-1] + [s[0]]
    c = max(jumps(out), jumps(back_seq))
    if best is None or c < best:
        best = c
print(best)

