def gen(rng):
    def fmt(s):
        return str(len(s)) + '\n' + ' '.join(map(str, s))
    def inc(n, lo, hi):
        return sorted(rng.sample(range(lo, hi + 1), n))
    tests = [fmt([0, 1]), fmt([0, 10**9]), fmt([5, 6, 7]), fmt([0, 1, 10**9]), fmt([0, 999999999, 10**9]),
             fmt([0, 1, 2, 3, 4, 5, 6])]
    for n in (3, 4, 5, 6, 7, 8, 9, 10):
        for _ in range(3):
            tests.append(fmt(inc(n, 0, rng.choice([n + 3, 30, 1000]))))
    N = 100000
    tests.append(fmt(inc(N, 0, 10**9)))
    tests.append(fmt(list(range(N))))
    tests.append(fmt([i * 10000 for i in range(N)]))
    tests.append(fmt(inc(N - 1, 0, 10**9 - 1) + [10**9]))
    return tests

